use serde::{Deserialize, Serialize};

#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
pub struct RequestInput {
    pub clearance_slug: String,
    pub pressurized_pods: i64,
    pub vacuum_pods: i64,
    pub docking_arms: i64,
    pub solar_flare: bool,
}

#[derive(Serialize)]
pub struct ResponseOutput {
    pub clearance_slug: String,
    pub payload_tally: i64,
    pub transfer_effort: i64,
    pub berth_allowance: i64,
    pub approved_effort: i64,
    pub spillover_effort: i64,
    pub orbit_passes: i64,
    pub clearance_rating: i64,
    pub clearance_phase: String,
}

pub fn score(pressurized_pods: i64, vacuum_pods: i64, docking_arms: i64, solar_flare: bool) -> i64 {
    let payload_tally = pressurized_pods + vacuum_pods;
    let transfer_effort = pressurized_pods * 8
        + vacuum_pods * 14
        + if solar_flare { docking_arms * 5 } else { 0 };
    let berth_allowance = docking_arms * 47;
    let approved_effort = transfer_effort.min(berth_allowance);
    let spillover_effort = (transfer_effort - berth_allowance).max(0);
    let orbit_passes = (payload_tally + 3) / 4;

    approved_effort + spillover_effort * 7 + orbit_passes * 6
}

pub fn calculate(input: &RequestInput) -> ResponseOutput {
    let payload_tally = input.pressurized_pods + input.vacuum_pods;
    let transfer_effort = input.pressurized_pods * 8
        + input.vacuum_pods * 14
        + if input.solar_flare { input.docking_arms * 5 } else { 0 };
    let berth_allowance = input.docking_arms * 47;
    let spillover_effort = (transfer_effort - berth_allowance).max(0);
    let clearance_phase = if spillover_effort == 0 {
        "cleared"
    } else if input.solar_flare {
        "flare_hold"
    } else {
        "routine_hold"
    };

    ResponseOutput {
        clearance_slug: input.clearance_slug.clone(),
        payload_tally,
        transfer_effort,
        berth_allowance,
        approved_effort: transfer_effort.min(berth_allowance),
        spillover_effort,
        orbit_passes: (payload_tally + 3) / 4,
        clearance_rating: score(
            input.pressurized_pods,
            input.vacuum_pods,
            input.docking_arms,
            input.solar_flare,
        ),
        clearance_phase: clearance_phase.into(),
    }
}

#[unsafe(no_mangle)]
pub extern "C" fn parley_browser_score(a0: i64, a1: i64, a2: i64, a3: i32) -> i64 {
    score(a0, a1, a2, a3 != 0)
}

